"use client";
import { useEffect, useState, useRef } from "react";
import { useRouter } from "next/navigation";
import { supabase } from "../lib/supabase";

const LOGO = "data:image/png;base64,";
const R_ICON = "data:image/png;base64,";
const ROYAL_PARK_LOGO = "data:image/png;base64,";

const CAT_KVARTIRY = "data:image/png;base64,";
const CAT_NOVOSTROYKI = "data:image/png;base64,";
const CATS = [
  { label: "Квартиры", key: "vtorichka", img: CAT_KVARTIRY, path: "M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z" },
  { label: "Новостройки", key: "pervichka", img: CAT_NOVOSTROYKI, path: "M3 21h18M5 21V7l7-4 7 4v14M9 21v-6h6v6" },
  { label: "Дома", key: "dom", path: "M3 21h18M6 21V10l6-4 6 4v11M10 21v-5h4v5" },
  { label: "Участки", key: "uchastok", path: "M7 20h10M12 20V10M8 10a4 4 0 0 1 8 0" },
  { label: "Коммерческая", key: "kommerciya", path: "M3 21h18M4 21V9l4-4h8l4 4v12M9 9h6M9 13h6M9 17h6" },
  { label: "Аренда", key: "arenda", path: "M12 2l2.5 5 5.5.8-4 4 1 5.5-5-2.6-5 2.6 1-5.5-4-4 5.5-.8z" },
  { label: "Иссык-Куль", key: "issykkul", path: "M3 18l5-8 4 5 3-4 6 7H3z" },
  { label: "Инвестиции", key: "investicii", path: "M3 17l6-6 4 4 8-8M21 3h-6M21 3v6" },
];

const NAV = [
  { label: "Главная", active: true, path: "/", icon: "M3 12l9-9 9 9M5 10v10h14V10" },
  { label: "Поиск", path: "/search/vse", icon: "M11 4a7 7 0 100 14 7 7 0 000-14zM21 21l-4.35-4.35" },
  { label: "Добавить", path: "/add", icon: "M12 5v14M5 12h14" },
  { label: "Реклама", path: "/ads", icon: "M3 17l6-6 4 4 8-8M21 3h-6M21 3v6" },
  { label: "Мои объекты", path: "/my", icon: "M4 4h7v7H4zM13 4h7v7h-7zM4 13h7v7H4zM13 13h7v7h-7z" },
  { label: "Профиль", path: "/profile", icon: "M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z" },
];

export default function HomePage() {
  const router = useRouter();
  const [counts, setCounts] = useState({ активен: 0, "на проверке": 0, архив: 0, всего: 0, сегодня: 0 });
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [langOpen, setLangOpen] = useState(false);
  const [lang, setLang] = useState("ru");
  const [catsOpen, setCatsOpen] = useState(false);
  const carouselRef = useRef(null);

  useEffect(() => {
    const el = carouselRef.current;
    if (!el) return;
    const timer = setInterval(() => {
      const cardWidth = el.firstChild ? el.firstChild.offsetWidth + 12 : 300;
      const atEnd = el.scrollLeft + el.clientWidth >= el.scrollWidth - 10;
      el.scrollTo({ left: atEnd ? 0 : el.scrollLeft + cardWidth, behavior: "smooth" });
    }, 4000);
    return () => clearInterval(timer);
  }, []);


  useEffect(() => {
    async function loadCounts() {
      try {
        const { count: total, error: e1 } = await supabase.from("listings").select("*", { count: "exact", head: true });
        const { count: active, error: e2 } = await supabase.from("listings").select("*", { count: "exact", head: true }).eq("status", "активен");
        const { count: review, error: e3 } = await supabase.from("listings").select("*", { count: "exact", head: true }).eq("status", "на проверке");
        const { count: archived, error: e4 } = await supabase.from("listings").select("*", { count: "exact", head: true }).eq("status", "архив");
        const todayStart = new Date(); todayStart.setHours(0, 0, 0, 0);
        const { count: today, error: e5 } = await supabase.from("listings").select("*", { count: "exact", head: true }).gte("created_at", todayStart.toISOString());
        if (e1 || e2 || e3 || e4 || e5) throw e1 || e2 || e3 || e4 || e5;
        setCounts({ всего: total || 0, активен: active || 0, "на проверке": review || 0, архив: archived || 0, сегодня: today || 0 });
      } catch (err) {
        setError(err.message);
      } finally {
        setLoading(false);
      }
    }
    loadCounts();
  }, []);

  return (
    <div className="app-shell">
      <div className="brand-strip">
        <div className="brand-strip-left">
          <img src={R_ICON} alt="" className="brand-strip-icon" />
          <div>
            <div className="brand-strip-text">RAYAN</div>
            <div className="brand-strip-sub">центр недвижимости</div>
          </div>
        </div>
        <button className="lang-switch" onClick={() => setLangOpen((v) => !v)}>
          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="1.8">
            <circle cx="12" cy="12" r="9" />
            <path d="M3 12h18M12 3a14 14 0 0 1 0 18M12 3a14 14 0 0 0 0 18" />
          </svg>
          <span>{lang.toUpperCase()}</span>
          <svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2"><path d="M6 9l6 6 6-6" /></svg>
        </button>
        {langOpen && (
          <div className="lang-dropdown">
            {["ru", "kg", "en"].map((l) => (
              <div key={l} className={`lang-option ${lang === l ? "active" : ""}`} onClick={() => { setLang(l); setLangOpen(false); }}>
                {l === "ru" ? "Русский" : l === "kg" ? "Кыргызча" : "English"}
              </div>
            ))}
          </div>
        )}
      </div>

      <div className="banner-carousel" ref={carouselRef}>
        <div className="banner-card banner-rayan">
          <img src={LOGO} alt="RAYAN" className="banner-rayan-logo" />
        </div>
        <div className="banner-card banner-royal">
          <img src={ROYAL_PARK_LOGO} alt="Royal Central Park" />
        </div>
        <div className="banner-card banner-invest">
          <div className="banner-invest-text">Инвестиции в строительство<br />от 50 000$</div>
        </div>
      </div>

      <div className="body-px">
        <div className="search-row">
          <div className="search">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#062E22" strokeWidth="2">
              <circle cx="11" cy="11" r="8" /><line x1="21" y1="21" x2="16.65" y2="16.65" />
            </svg>
            <input placeholder="Поиск объектов..." onFocus={() => router.push("/search/vse")} readOnly />
          </div>
          <button className="filter-btn" onClick={() => router.push("/search/vse")}>
            <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="1.8">
              <path d="M4 6h16M7 12h10M10 18h4" />
            </svg>
            <span>Фильтр</span>
          </button>
        </div>

        <div className="stats">
          {[["активен", "Активные"], ["на проверке", "На проверке"], ["архив", "Архив"]].map(([key, label]) => (
            <div key={key} className="stat-card" style={{ cursor: "pointer" }} onClick={() => router.push(`/my?status=${encodeURIComponent(key)}`)}>
              <div className="stat-num">{loading ? "…" : counts[key]}</div>
              <div className="stat-label">{label}</div>
            </div>
          ))}
        </div>
        <div className="stats" style={{ marginTop: 10 }}>
          <div className="stat-card" style={{ cursor: "pointer", flex: 1 }} onClick={() => router.push("/my")}>
            <div className="stat-num">{loading ? "…" : counts["сегодня"]}</div>
            <div className="stat-label">Новых сегодня</div>
          </div>
        </div>

        {error && <div className="status-msg error">Не удалось загрузить данные: {error}</div>}

        <div className="section-label">ТИП НЕДВИЖИМОСТИ</div>
        <div className="cats-row">
          {CATS.map((c, i) => (
            <button key={i} className="cat-tile" onClick={() => router.push(`/search/${c.key}`)}>
              <div className="cat-tile-icon">
                {c.img ? (
                  <img src={c.img} alt="" className="cat-tile-img" />
                ) : (
                  <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="#B8B8BE" strokeWidth="1.6">
                    <path d={c.path} />
                  </svg>
                )}
              </div>
              <span className="cat-tile-label">{c.label}</span>
            </button>
          ))}
        </div>
        <button className="all-cats-btn" onClick={() => setCatsOpen(true)}>
          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2">
            <rect x="3" y="3" width="7" height="7" /><rect x="14" y="3" width="7" height="7" />
            <rect x="3" y="14" width="7" height="7" /><rect x="14" y="14" width="7" height="7" />
          </svg>
          <span>Все категории</span>
        </button>
      </div>

      {catsOpen && (
        <div className="cats-modal-backdrop" onClick={() => setCatsOpen(false)}>
          <div className="cats-modal" onClick={(e) => e.stopPropagation()}>
            <div className="cats-modal-handle" />
            <div className="cats-modal-header">
              <span>Категории</span>
              <span className="cats-modal-close" onClick={() => setCatsOpen(false)}>✕</span>
            </div>
            {CATS.map((c, i) => (
              <div key={i} className="cats-modal-row" onClick={() => { setCatsOpen(false); router.push(`/search/${c.key}`); }}>
                <div className="cats-modal-icon">
                  {c.img ? (
                    <img src={c.img} alt="" className="cats-modal-img" />
                  ) : (
                    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="#0A2E22" strokeWidth="1.8">
                      <path d={c.path} />
                    </svg>
                  )}
                </div>
                <span className="cats-modal-label">{c.label}</span>
                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#8B8B90" strokeWidth="2"><path d="M9 6l6 6-6 6" /></svg>
              </div>
            ))}
          </div>
        </div>
      )}

      <div className="bottomnav">
        {NAV.map((n, i) =>
          n.label === "Добавить" ? (
            <div key={i} className="nav-fab-wrap" onClick={() => router.push(n.path)} style={{ cursor: "pointer" }}>
              <div className="nav-fab">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2.5">
                  <line x1="12" y1="5" x2="12" y2="19" /><line x1="5" y1="12" x2="19" y2="12" />
                </svg>
              </div>
            </div>
          ) : (
            <div key={i} className={`nav-item ${n.active ? "active" : ""}`} onClick={() => router.push(n.path)} style={{ cursor: "pointer" }}>
              <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke={n.active ? "var(--green-accent)" : "#7FA396"} strokeWidth={n.active ? 2.2 : 1.7}>
                <path d={n.icon} />
              </svg>
              <span>{n.label}</span>
            </div>
          )
        )}
      </div>
    </div>
  );
}
